from itertools import combinations
from math import floor


def turan_graph(n: int, p: int) -> set[frozenset]:
    """Edge set of the Turan graph T(n, p): i ~ j iff i % p != j % p."""
    return {
        frozenset((i, j))
        for i in range(n)
        for j in range(i + 1, n)
        if i % p != j % p
    }


def mantel_bound(n: int) -> int:
    """Maximum edges in a triangle-free graph on n vertices."""
    return floor(n * n / 4)


# T(n, 2) realises the Mantel bound exactly:
for n in range(2, 12):
    assert len(turan_graph(n, 2)) == mantel_bound(n)

from itertools import combinations


def triangles(n: int, edges: set[frozenset]) -> list[tuple[int, int, int]]:
    out = []
    for a, b, c in combinations(range(n), 3):
        if {frozenset((a, b)), frozenset((a, c)), frozenset((b, c))} <= edges:
            out.append((a, b, c))
    return out


def greedy_triangle_removal(n: int, edges: set[frozenset]) -> tuple[set[frozenset], int]:
    """Return a triangle-free subgraph and the number of deleted edges.

    Certificate: deletions <= number of triangles in the input graph.
    """
    edges = set(edges)
    removed = 0
    while True:
        tri = triangles(n, edges)
        if not tri:
            return edges, removed
        a, b, _ = tri[0]
        edges.discard(frozenset((a, b)))  # delete one edge per triangle
        removed += 1
